    "id": "00000024-f3b0-5feb-b957-c0c19708a916",
    "name_es": "Sentadilla Frontal en Banco con Barra",
    "name_en": "Barbell Bench Front Squat",
    "name_pt": "Agachamento Frontal no Banco com Barra",
    "nivel_1_tipo": "muscular",
