    "name_es": "Fondos en Banco (con Rodillas Flexionadas)",
    "name_en": "Bench Dip (Knees Bent)",
    "name_pt": "Mergulho no Banco (com Joelhos Flexionados)",
    "nivel_1_tipo": "muscular",
