    "id": "00001301-b494-543b-9a30-d1f12c230e0d",
    "name_es": "Press de Pecho Interno en Máquina",
    "name_en": "Machine Inner Chest Press",
    "name_pt": "Supino Fechado para Peitoral na Máquina",
    "nivel_1_tipo": "muscular",
