    "id": "00000830-65e2-52fb-96c4-9ceca7c4411b",
    "name_es": "Fondos en Banco con Lastre",
    "name_en": "Weighted Bench Dip",
    "name_pt": "Mergulho no Banco com Carga",
    "nivel_1_tipo": "muscular",
