/**
 * HELPER CENTRALIZADO: Resolución limpia de Media (GIFs y Videos MP4)
 * Mapea sin errores cualquier registro hacia "EJERCICIOS/exercises-final/videos" o "EJERCICIOS/videos_loop_final"
 */
function resolveExerciseMediaUrl(video_local_path) {
    if (!video_local_path) {
        return {
            url: '',
            isVideo: false,
            isGif: false,
            filename: '',
            renderHtml: () => '<div class="exercise-media-placeholder"></div>'
        };
    }

    const clean = String(video_local_path).trim().replace(/\\/g, '/');
    const filename = clean.split('/').pop();
    const isVideo = clean.toLowerCase().endsWith('.mp4');
    const isGif = clean.toLowerCase().endsWith('.gif');

    // Rutas directas verificadas en el repositorio
    let resolvedUrl = isVideo 
        ? `EJERCICIOS/videos_loop_final/${filename}`
        : `EJERCICIOS/exercises-final/videos/${filename}`;

    return {
        url: resolvedUrl,
        isVideo,
        isGif,
        filename,
        renderHtml: (extraClass = '', extraStyle = '') => {
            if (isVideo) {
                return `<video autoplay loop muted playsinline preload="metadata" class="${extraClass}" style="${extraStyle}"><source src="${resolvedUrl}" type="video/mp4"></video>`;
            } else {
                return `<img src="${resolvedUrl}" alt="" loading="lazy" class="${extraClass}" style="${extraStyle}">`;
            }
        }
    };
}

/**
 * HELPER DE DIVULGACIÓN PROGRESIVA: Parsea summary_detailed_movement en 3 pasos escaneables
 */
function parseExerciseSummarySteps(summaryText) {
    if (!summaryText) {
        return [
            { stepNum: 1, label: 'Posición / Setup', text: 'Alineación articular y postura base.' },
            { stepNum: 2, label: 'Ejecución / Execution', text: 'Rango de movimiento biomecánico estricto.' },
            { stepNum: 3, label: 'Control / Controle', text: 'Cadencia excéntrica y respiración diafragmática.' }
        ];
    }

    const text = String(summaryText).trim();
    const pos1 = text.indexOf('1.');
    const pos2 = text.indexOf('2.');
    const pos3 = text.indexOf('3.');

    if (pos1 !== -1 && pos2 !== -1 && pos3 !== -1) {
        const step1Raw = text.substring(pos1, pos2).trim();
        const step2Raw = text.substring(pos2, pos3).trim();
        const step3Raw = text.substring(pos3).trim();

        const extract = (raw, num, defaultLabel) => {
            const clean = raw.replace(new RegExp(`^${num}\\.\\s*`), '');
            const colonIdx = clean.indexOf(':');
            if (colonIdx !== -1 && colonIdx < 30) {
                return {
                    stepNum: num,
                    label: clean.substring(0, colonIdx).trim(),
                    text: clean.substring(colonIdx + 1).trim()
                };
            }
            return {
                stepNum: num,
                label: defaultLabel,
                text: clean
            };
        };

        return [
            extract(step1Raw, 1, 'Posición / Setup'),
            extract(step2Raw, 2, 'Ejecución / Execution'),
            extract(step3Raw, 3, 'Control / Controle')
        ];
    }

    return [
        { stepNum: 1, label: 'Instrucción General', text: summaryText }
    ];
}

/**
 * MOTOR DE CÁLCULO CALÓRICO FISIOLÓGICO POR SERIE Y POR EJERCICIO
 * Ecuación Maestra SENS:
 *   Trabajo_Mecanico_Kcal = reps_completadas * exercise.calories_per_rep * (peso_usuario_kg / 75.0)
 *   Factor_EPOC_Descanso = (exercise.nivel_1_tipo === 'movilidad') ? 1.2 : 2.2
 *   Recuperacion_EPOC_Kcal = (segundos_descanso_reales_o_default / 60.0) * Factor_EPOC_Descanso * (peso_usuario_kg / 75.0)
 *   Kcal_Serie = Trabajo_Mecanico_Kcal + Recuperacion_EPOC_Kcal
 */
function calculateExerciseSetKcal(exercise, reps = 10, athleteWeight = 75.0, restSeconds = null) {
    if (!exercise) {
        return {
            trabajoMecanicoKcal: 4.5,
            epocKcal: 3.3,
            kcalSerie: 7.8,
            repsEquivalentes: 10,
            descansoSegundos: 90
        };
    }

    const peso = (athleteWeight && athleteWeight > 0) ? athleteWeight : 75.0;
    const pesoFactor = peso / 75.0;
    const calPerRep = (typeof exercise.calories_per_rep === 'number' && exercise.calories_per_rep > 0)
        ? exercise.calories_per_rep
        : 0.45;

    // Para ejercicios medidos por tiempo / isométricos (planchas, cardio), cada 5 segundos de trabajo activo = 1 rep
    let repsEquivalentes = 10;
    const repsStr = String(reps || '10').toLowerCase().trim();
    const nums = repsStr.match(/\d+/g);
    if (nums && nums.length > 0) {
        if (repsStr.includes('seg') || repsStr.includes('sec') || repsStr.includes('s')) {
            const secs = parseInt(nums[0], 10) || 30;
            repsEquivalentes = Math.max(1, Math.round(secs / 5.0));
        } else if (nums.length >= 2) {
            repsEquivalentes = Math.round((parseInt(nums[0], 10) + parseInt(nums[1], 10)) / 2);
        } else {
            repsEquivalentes = parseInt(nums[0], 10) || 10;
        }
    } else if (typeof reps === 'number' && reps > 0) {
        repsEquivalentes = reps;
    }

    const trabajoMecanicoKcal = repsEquivalentes * calPerRep * pesoFactor;
    const factorEpoc = (exercise.nivel_1_tipo === 'movilidad') ? 1.2 : 2.2;
    const descansoSegundos = (restSeconds !== null && restSeconds !== undefined && restSeconds > 0)
        ? restSeconds
        : (exercise.default_rest_seconds || 90);

    const epocKcal = (descansoSegundos / 60.0) * factorEpoc * pesoFactor;
    const kcalSerie = Math.round((trabajoMecanicoKcal + epocKcal) * 10) / 10;

    return {
        trabajoMecanicoKcal: Math.round(trabajoMecanicoKcal * 10) / 10,
        epocKcal: Math.round(epocKcal * 10) / 10,
        kcalSerie,
        repsEquivalentes,
        descansoSegundos
    };
}

/**
 * Calcula el gasto total acumulado de un ejercicio (series * kcalSerie)
 */
function calculateExerciseKcal(ex, customSets = null, customReps = null, athleteWeight = 75.0, customRest = null) {
    if (!ex) return { kcalPerRep: 0.45, kcalPerSet: 7.8, totalKcal: 31.2, sets: 4, repsAvg: 10 };
    const setsNum = parseInt(customSets || ex.default_sets || ex.sets || 4, 10) || 4;
    const setData = calculateExerciseSetKcal(ex, customReps || ex.default_reps || ex.reps || 10, athleteWeight, customRest || ex.default_rest_seconds);

    const kcalPerRep = Math.round((ex.calories_per_rep || 0.45) * ((athleteWeight || 75) / 75.0) * 100) / 100;
    const kcalPerSet = setData.kcalSerie;
    const totalKcal = Math.round(kcalPerSet * setsNum);

    return {
        kcalPerRep,
        kcalPerSet,
        totalKcal,
        sets: setsNum,
        repsAvg: setData.repsEquivalentes,
        trabajoMecanicoKcal: setData.trabajoMecanicoKcal,
        epocKcal: setData.epocKcal
    };
}

/**
 * Taxonomía descriptiva normalizada
 */
function getExerciseTaxonomy(ex) {
    if (!ex) return { type: 'muscular', typeLabel: 'Muscular', muscleGroup: 'piernas', muscleLabel: 'Piernas', subMuscle: null, subMuscleLabel: '' };

    const type = (ex.nivel_1_tipo || 'muscular').toLowerCase();
    const muscleGroup = (ex.nivel_2_grupo_muscular || ex.category || 'piernas').toLowerCase();
    const subMuscle = (muscleGroup === 'piernas' && ex.nivel_3_submusculo_piernas)
        ? ex.nivel_3_submusculo_piernas.toLowerCase()
        : null;

    const labelMap = {
        muscular: 'Muscular',
        movilidad: 'Movilidad',
        cardio: 'Cardio',
        piernas: 'Piernas',
        espalda: 'Espalda',
        abdominales: 'Abdominales',
        pecho: 'Pecho',
        biceps: 'Bíceps',
        hombros: 'Hombros',
        triceps: 'Tríceps',
        antebrazos: 'Antebrazos',
        zona_lumbar: 'Zona Lumbar',
        cuadriceps: 'Cuádriceps',
        isquios: 'Isquios',
        gluteos: 'Glúteos',
        gemelos: 'Gemelos',
        abductores: 'Abductores',
        aductores: 'Aductores'
    };

    return {
        type,
        typeLabel: labelMap[type] || type,
        muscleGroup,
        muscleLabel: labelMap[muscleGroup] || muscleGroup,
        subMuscle,
        subMuscleLabel: subMuscle ? (labelMap[subMuscle] || subMuscle) : ''
    };
}

/**
 * Helper i18n para obtener textos localizados según el idioma activo del usuario ('es' | 'en' | 'pt')
 */
function getExerciseLocalized(ex, lang = 'es') {
    if (!ex) return { name: '', cue: '', summary: '', detailed: '', lang: 'es' };
    const targetLang = ['es', 'en', 'pt'].includes(lang) ? lang : 'es';

    return {
        name: ex['name_' + targetLang] || ex.name_es || ex.name || '',
        cueTechnical: ex['cue_technical_' + targetLang] || ex.cue_technical_es || ex.cue || '',
        summaryMovement: ex['summary_detailed_movement_' + targetLang] || ex.summary_detailed_movement_es || ex.execution || '',
        detailedMovement: ex['detailed_movement_' + targetLang] || ex.detailed_movement_es || '',
        lang: targetLang
    };
}

/**
 * Resuelve un ejercicio desde cualquier identificador o nombre aplicando overrides
 */
function getResolvedExercise(exOrId, athleteId = null) {
    if (!exOrId) return null;

    let searchId = typeof exOrId === 'string' ? exOrId.trim() : (exOrId.id || '').trim();
    let searchName = typeof exOrId === 'string' ? exOrId.trim() : (exOrId.name || exOrId.name_es || '').trim();

    // 1. Resolver mapeo de ID legado (ej. ex-q1, ex-101 -> UUID)
    if (SENS_LEGACY_EXERCISE_ID_MAP[searchId]) {
        searchId = SENS_LEGACY_EXERCISE_ID_MAP[searchId];
    }

    // 2. Buscar por ID directo en mapa O(1)
    let baseEx = SENS_EXERCISE_BY_ID.get(searchId);

    // 3. Buscar por nombre normalizado
    if (!baseEx && searchName) {
        const normalize = (str) => (str || '').toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/^\d+[\.\s\-]+/, '').trim();
        const cleanName = normalize(searchName);
        baseEx = SENS_EXERCISE_BY_NAME_NORM.get(cleanName);

        if (!baseEx) {
            baseEx = SENS_EXERCISE_LIBRARY.find(e => {
                const es = normalize(e.name_es);
                const en = normalize(e.name_en);
                const pt = normalize(e.name_pt);
                return es === cleanName || en === cleanName || pt === cleanName ||
                       cleanName.includes(es) || es.includes(cleanName) ||
                       cleanName.includes(en) || en.includes(cleanName);
            });
        }
    }

    if (!baseEx && typeof exOrId === 'object') {
        baseEx = exOrId;
    }
    if (!baseEx) return null;

    let resolved = Object.assign({}, baseEx);

    // 1. Override Global de Nico (localStorage)
    try {
        if (typeof localStorage !== 'undefined') {
            const globalRaw = localStorage.getItem('sens_global_exercise_overrides_v1');
            if (globalRaw) {
                const globalMap = JSON.parse(globalRaw);
                if (globalMap && globalMap[resolved.id]) {
                    resolved = Object.assign(resolved, globalMap[resolved.id], { _hasGlobalOverride: true });
                }
            }
        }
    } catch (e) {}

    // 2. Override Puntual del Alumno
    const targetAthId = athleteId || (typeof window !== 'undefined' && window.AppState && window.AppState.currentUser && window.AppState.currentUser.id) || null;
    if (targetAthId && typeof localStorage !== 'undefined') {
        try {
            const athRaw = localStorage.getItem('sens_athlete_exercise_overrides_' + targetAthId);
            if (athRaw) {
                const athMap = JSON.parse(athRaw);
                if (athMap && athMap[resolved.id]) {
                    resolved = Object.assign(resolved, athMap[resolved.id], { _hasAthleteOverride: true });
                }
            }
        } catch (e) {}
    }

    const tax = getExerciseTaxonomy(resolved);
    resolved.taxonomy = tax;
    resolved.type_level1 = tax.type;
    resolved.group_level2 = tax.muscleGroup;
    resolved.sub_level3 = tax.subMuscle;
    resolved.video_url = resolved.video_local_path;
    resolved.video = resolved.video_local_path;

    return resolved;
}

function getResolvedExerciseVideoUrl(exerciseOrId) {
    if (!exerciseOrId) return '';
    const ex = getResolvedExercise(exerciseOrId);
    if (!ex) return '';
    return resolveExerciseMediaUrl(ex.video_local_path).url;
}

function hydrateExerciseLibraryInMemory() {
    let globalMap = {};
    try {
        if (typeof localStorage !== 'undefined') {
            const raw = localStorage.getItem('sens_global_exercise_overrides_v1');
            if (raw) globalMap = JSON.parse(raw) || {};
        }
    } catch (e) {}

    SENS_EXERCISE_LIBRARY.forEach(ex => {
        if (globalMap[ex.id]) {
            Object.assign(ex, globalMap[ex.id]);
        }
        const tax = getExerciseTaxonomy(ex);
        ex.type_level1 = tax.type;
        ex.group_level2 = tax.muscleGroup;
        ex.sub_level3 = tax.subMuscle;
        ex.exercise_type = tax.type;
        ex.category = tax.muscleGroup;
        ex.muscle_group = tax.muscleGroup;
        ex.video_url = ex.video_local_path;
        ex.video = ex.video_local_path;
    });
}

hydrateExerciseLibraryInMemory();

// Exportaciones globales para navegador y Node.js
if (typeof window !== 'undefined') {
    window.SENS_EXERCISE_LIBRARY = SENS_EXERCISE_LIBRARY;
    window.SENS_EXERCISE_BY_ID = SENS_EXERCISE_BY_ID;
    window.SENS_LEGACY_EXERCISE_ID_MAP = SENS_LEGACY_EXERCISE_ID_MAP;
    window.SENS_TRAINING_TAXONOMY_TREE = SENS_TRAINING_TAXONOMY_TREE;
    window.resolveExerciseMediaUrl = resolveExerciseMediaUrl;
    window.parseExerciseSummarySteps = parseExerciseSummarySteps;
    window.calculateExerciseSetKcal = calculateExerciseSetKcal;
    window.calculateExerciseKcal = calculateExerciseKcal;
    window.getExerciseTaxonomy = getExerciseTaxonomy;
    window.getExerciseLocalized = getExerciseLocalized;
    window.getResolvedExercise = getResolvedExercise;
    window.getResolvedExerciseVideoUrl = getResolvedExerciseVideoUrl;
    window.hydrateExerciseLibraryInMemory = hydrateExerciseLibraryInMemory;
    window.EXERCISE_CATALOG = SENS_EXERCISE_LIBRARY;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        SENS_EXERCISE_LIBRARY,
        SENS_EXERCISE_BY_ID,
        SENS_LEGACY_EXERCISE_ID_MAP,
        SENS_TRAINING_TAXONOMY_TREE,
        resolveExerciseMediaUrl,
        parseExerciseSummarySteps,
        calculateExerciseSetKcal,
        calculateExerciseKcal,
        getExerciseTaxonomy,
        getExerciseLocalized,
        getResolvedExercise,
        getResolvedExerciseVideoUrl,
        hydrateExerciseLibraryInMemory
    };
}
